int boot_read_bank_header(uint8_t area_id,
			  struct mcuboot_img_header *header,
			  size_t header_size)
{
	int rc;
	struct boot_img_hdr_v1 v1_raw;
	struct mcuboot_img_sem_ver *sem_ver;
	size_t v1_min_size = sizeof(uint32_t) +
			     sizeof(struct mcuboot_img_header_v1);

	/*
	 * Only version 1 headers are supported.
	 */
	if (header_size < v1_min_size) {
		return -ENOMEM;
	}

	/*
	 * Read and sanity-check the raw header.
	 */
	rc = boot_read_v1_header(area_id, &v1_raw);
	if (rc) {
		return rc;
	}

	/*
	 * Copy the raw header data we need to the output.
	 *
	 * The image size is the sum of the raw header's size and image
	 * size fields, as header_size only reflects the size of the
	 * image itself.
	 */
	header->mcuboot_version = 1U;
	header->h.v1.image_size = v1_raw.ih_hdr_size + v1_raw.ih_img_size;
	sem_ver = &header->h.v1.sem_ver;
	sem_ver->major = v1_raw.ih_ver.iv_major;
	sem_ver->minor = v1_raw.ih_ver.iv_minor;
	sem_ver->revision = v1_raw.ih_ver.iv_revision;
	sem_ver->build_num = v1_raw.ih_ver.iv_build_num;
	return 0;
}

